#!/usr/bin/env python3
"""Writes ctx.c: every project header, preprocessed into one file.

ctx.c is the context m2c needs to know our types and function prototypes; it
can also be pasted into the "Context" box on https://decomp.me.

Usage: m2ctx.py
"""

import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
# Headers generated by splat contain only asm macros, which m2c does not need.
SKIP = {"include_asm.h"}


def headers() -> list:
    found = []
    for directory in ("include", "src"):
        for header in sorted((ROOT / directory).rglob("*.h")):
            if header.name not in SKIP:
                found.append(header.relative_to(ROOT).as_posix())
    return found


def main():
    source = "".join(f'#include "{header}"\n' for header in headers())
    result = subprocess.run(
        ["cpp", "-P", "-undef", "-nostdinc", "-I", "include", "-I", ".",
         "-DM2CTX", "-DTARGET_PSX", "-"],
        input=source, capture_output=True, text=True, cwd=ROOT,
    )
    if result.returncode != 0:
        sys.stderr.write(result.stderr)
        return result.returncode
    (ROOT / "ctx.c").write_text(result.stdout, encoding="utf-8", newline="\n")
    print("записан ctx.c")
    return 0


if __name__ == "__main__":
    sys.exit(main())
